    ReleaseInputInterface;

   local:
    /* Internal cross-TU helpers (non-static, would otherwise be exported) */
    GetDevManager;
    InstanceReporterHdi;
    InstanceControllerHdi;
    UpdateDevFullInfo;

    /* Internal global state */
    g_devManager;

    /* Linker-generated */
    _init;
    _fini;

    /* Catch-all: hide everything else */
    *;
};